       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         transform: translateY(-180%);
         padding: 0.85rem 1rem;
         border-radius: 999px;
         background: var(--surface-strong);
         border: 2px solid var(--accent);
         font-weight: 600;
         text-decoration: none;
         z-index: 10;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       main {
         display: grid;
         place-items: center;
         padding: 2rem 1rem 3rem;
       }

       .page-shell {
         width: min(100%, 920px);
         display: grid;
         gap: 1.5rem;
       }

       .page-header {
         padding: 0.5rem 0.25rem 0;
       }

       .eyebrow {
         margin: 0 0 0.5rem;
         font-size: 0.875rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
         color: var(--accent-strong);
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 4vw, 3.25rem);
         line-height: 1.05;
         letter-spacing: -0.04em;
       }

       .intro {
         margin: 0.85rem 0 0;
         max-width: 58ch;
         color: var(--muted);
         font-size: 1.05rem;
         line-height: 1.65;
       }

       .form-card {
         padding: clamp(1.25rem, 3vw, 2rem);
         border: 1px solid rgba(214, 224, 238, 0.8);
         border-radius: var(--radius);
         background: var(--surface);
         box-shadow: var(--shadow);
         backdrop-filter: blur(18px);
       }

       form {
         display: grid;
         gap: 1.15rem;
       }

       .form-grid {
         display: grid;
         gap: 1.15rem;
       }

       .form-field {
         display: grid;
         gap: 0.45rem;
       }

       .visually-hidden {
         position: absolute;
         width: 1px;
         height: 1px;
         padding: 0;
         margin: -1px;
         overflow: hidden;
         clip: rect(0, 0, 0, 0);
         white-space: nowrap;
         border: 0;
       }

       label {
         font-weight: 650;
         line-height: 1.2;
       }

       .required-mark {
         color: var(--accent-strong);
       }

       .field-hint,
       .field-error {
         margin: 0;
         font-size: 0.95rem;
         line-height: 1.45;
       }

       .field-hint {
         color: var(--muted);
       }

       .field-error {
         color: var(--error);
       }

       input {
         width: 100%;
         min-height: 3rem;
         padding: 0.85rem 1rem;
         border: 1.5px solid var(--border);
         border-radius: 16px;
         background: var(--surface-strong);
         color: var(--text);
         font: inherit;
         transition:
           border-color 150ms ease,
           box-shadow 150ms ease,
           background-color 150ms ease;
       }

       input::placeholder {
         color: #8a96a8;
       }

       input:hover {
         border-color: #b9c7da;
       }

       input:focus {
         outline: none;
         border-color: var(--accent);
         box-shadow: 0 0 0 4px rgba(36, 87, 214, 0.16);
       }

       input[aria-invalid="true"] {
         border-color: var(--error);
         background: var(--error-bg);
         box-shadow: 0 0 0 4px rgba(180, 35, 24, 0.12);
       }

       .submit-row {
         display: grid;
         gap: 0.75rem;
         margin-top: 0.25rem;
       }

       button {
         justify-self: start;
         min-height: 3.25rem;
         padding: 0.9rem 1.3rem;
         border: 0;
         border-radius: 999px;
         background: linear-gradient(135deg, var(--accent), #4f7dff);
         color: #fff;
         font: inherit;
         font-weight: 700;
         letter-spacing: 0.01em;
         cursor: pointer;
         box-shadow: 0 12px 28px rgba(36, 87, 214, 0.24);
         transition:
           transform 150ms ease,
           box-shadow 150ms ease,
           filter 150ms ease;
       }

       button:hover {
         transform: translateY(-1px);
         box-shadow: 0 16px 32px rgba(36, 87, 214, 0.28);
       }

       button:focus-visible {
         outline: 3px solid #0f172a;
         outline-offset: 3px;
       }

       button:active {
         transform: translateY(0);
         filter: brightness(0.98);
       }

       @media (max-width: 640px) {
         main {
           padding: 1rem 0.75rem 2rem;
         }

         .form-card {
           border-radius: 20px;
         }

         button {
           width: 100%;
           justify-self: stretch;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         html {
           scroll-behavior: auto;
         }

         *,
         *::before,
         *::after {
           animation-duration: 0.01ms !important;
           animation-iteration-count: 1 !important;
           transition-duration: 0.01ms !important;
         }
       }

       @media (forced-colors: active) {
         .skip-link,
         .form-card,
         input,
         button {
           forced-color-adjust: auto;
         }

         input[aria-invalid="true"] {
           outline: 2px solid Highlight;
           box-shadow: none;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>

     <main id="maincontent">
       <div class="page-shell">
         <header class="page-header">
           <p class="eyebrow">Support</p>
           <h1>Contact the support team</h1>
           <p class="intro">
             Send us your details and we’ll route your request to the right specialist.
             Full name and email address are required. Phone number is optional.
           </p>
         </header>

         <section class="form-card" aria-labelledby="contact-form-heading">
           <h2 id="contact-form-heading" class="visually-hidden">Support contact form</h2>

           <form id="contact-form" novalidate>
             <div class="form-grid">
               <div class="form-field">
                 <label for="full-name">
                   Full name <span class="required-mark" aria-hidden="true">*</span>
                 </label>
                 <input
                   id="full-name"
                   name="fullName"
                   type="text"
                   autocomplete="name"
                   required
                   aria-describedby="full-name-error"
                   aria-invalid="false"
                 />
                 <p class="field-error" id="full-name-error" hidden aria-live="polite"></p>
               </div>

               <div class="form-field">
                 <label for="email-address">
                   Email address <span class="required-mark" aria-hidden="true">*</span>
                 </label>
                 <input
                   id="email-address"
                   name="email"
                   type="email"
                   autocomplete="email"
                   required
                   aria-describedby="email-address-error"
                   aria-invalid="false"
                 />
                 <p class="field-error" id="email-address-error" hidden aria-live="polite"></p>
               </div>

               <div class="form-field">
                 <label for="phone-number">Phone number</label>
                 <input
                   id="phone-number"
                   name="phone"
                   type="tel"
                   inputmode="tel"
                   autocomplete="tel"
                   aria-describedby="phone-number-hint phone-number-error"
                   aria-invalid="false"
                   placeholder="+1 555 123 4567"
                 />
                 <p class="field-hint" id="phone-number-hint">
                   Optional. Use a number such as +1 555 123 4567 or (555) 123-4567.
                 </p>
                 <p class="field-error" id="phone-number-error" hidden aria-live="polite"></p>
               </div>
             </div>

             <div class="submit-row">
               <button type="submit">Send message</button>
             </div>
           </form>
         </section>
       </div>
     </main>

     <script>
       (() => {
         const form = document.getElementById("contact-form");
         const fields = [
           {
             input: document.getElementById("full-name"),
             error: document.getElementById("full-name-error"),
             validate: (value) => {
               if (!value.trim()) {
                 return "Error: Enter your full name.";
               }
               return "";
             },
           },
           {
             input: document.getElementById("email-address"),
             error: document.getElementById("email-address-error"),
             validate: (value) => {
               if (!value.trim()) {
                 return "Error: Enter your email address.";
               }

               if (!value.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)) {
                 return "Error: Enter a valid email address, like name@example.com.";
               }

               return "";
             },
           },
           {
             input: document.getElementById("phone-number"),
             error: document.getElementById("phone-number-error"),
             validate: (value) => {
               const trimmed = value.trim();

               if (!trimmed) {
                 return "";
               }

               const digits = trimmed.replace(/\D/g, "");
               const allowedChars = /^[+()\d\s.-]+$/;

               if (!allowedChars.test(trimmed) || digits.length < 7) {
                 return "Error: Enter a valid phone number, such as +1 555 123 4567.";
               }

               return "";
             },
           },
         ];

         const setFieldState = (field, message) => {
           const isInvalid = Boolean(message);

           field.input.setAttribute("aria-invalid", String(isInvalid));
           field.error.textContent = message;
           field.error.hidden = !message;
         };

         const validateField = (field) => {
           const message = field.validate(field.input.value);
           setFieldState(field, message);
           return !message;
         };

         fields.forEach((field) => {
           field.input.addEventListener("blur", () => validateField(field));
           field.input.addEventListener("input", () => {
             if (field.error.textContent) {
               validateField(field);
             }
           });
         });

         form.addEventListener("submit", (event) => {
           let firstInvalid = null;
           let allValid = true;

           fields.forEach((field) => {
             const isValid = validateField(field);
             if (!isValid && !firstInvalid) {
               firstInvalid = field.input;
             }
             allValid = allValid && isValid;
           });

           if (!allValid) {
             event.preventDefault();
             firstInvalid?.focus();
           }
         });
       })();
     </script>
   </body>
 </html>

')
